// Race: every worker writes the same variable.
std::uint64_t total = 0;
void worker_bad(Rows rows) { for (auto y : rows) total += render_row(y); }

// Fix: one local accumulator per worker, merged after join.
std::uint64_t worker_ok(Rows rows) {
	std::uint64_t local = 0;
	for (auto y : rows) local += render_row(y);
	return local;
}

